import unittest

from solucao import garantir
from solucao import tirar_ultimo
from solucao import comanda_de


class TestTirarEDevolver(unittest.TestCase):
    def test_garantir_devolve_o_valor_guardado(self):
        """garantir devolve o valor quando a chave ja existe"""
        d = {"a": 1}
        self.assertEqual(garantir(d, "a", 9), 1)

    def test_garantir_guarda_o_padrao(self):
        """garantir guarda o padrao quando a chave nao existe"""
        d = {"a": 1}
        self.assertEqual(garantir(d, "b", 0), 0)
        self.assertEqual(d, {"a": 1, "b": 0})

    def test_tirar_ultimo_devolve_e_tira_o_ultimo_par(self):
        """tirar_ultimo devolve o ultimo par e o tira do dicionario"""
        d = {"a": 1, "b": 2}
        self.assertEqual(tirar_ultimo(d), ("b", 2))
        self.assertEqual(d, {"a": 1})

    def test_comanda_de_usa_o_numero_em_texto(self):
        """comanda_de guarda a mesa em texto e devolve a comanda que ja existe"""
        comandas = {}
        self.assertEqual(comanda_de(comandas, 7), "sem nome")
        self.assertEqual(comandas, {"7": "sem nome"})
        self.assertEqual(comanda_de(comandas, 12), "sem nome")
        self.assertEqual(comandas, {"7": "sem nome", "12": "sem nome"})
        comandas = {"7": "ana"}
        self.assertEqual(comanda_de(comandas, 7), "ana")

